const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const specialties=[['♡','Cardiology'],['♧','Neurology'],['✧','Dermatology'],['♙','Pediatrics'],['⌘','Orthopedics'],['⊕','General Medicine']];
const doctors=[
 {id:1,name:'Dr. Farhana Ahmed',specialty:'Cardiology',degree:'MBBS, FCPS (Cardiology)',experience:12,clinic:'Green Life Medical Center',city:'Dhaka',fee:1200,img:'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=240&h=280&fit=crop'},
 {id:2,name:'Dr. Arif Rahman',specialty:'Neurology',degree:'MBBS, MD (Neurology)',experience:15,clinic:'Central Care Hospital',city:'Dhaka',fee:1500,img:'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=240&h=280&fit=crop'},
 {id:3,name:'Dr. Nusrat Jahan',specialty:'Dermatology',degree:'MBBS, DDV (Dermatology)',experience:9,clinic:'SHIFA Skin Clinic',city:'Chattogram',fee:900,img:'https://images.unsplash.com/photo-1594824476967-48c8b964273f?w=240&h=280&fit=crop'},
 {id:4,name:'Dr. Tanvir Hasan',specialty:'Pediatrics',degree:'MBBS, FCPS (Pediatrics)',experience:11,clinic:'Little Steps Medical Center',city:'Dhaka',fee:1000,img:'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=240&h=280&fit=crop'},
 {id:5,name:'Dr. Samira Khan',specialty:'General Medicine',degree:'MBBS, FCPS (Medicine)',experience:8,clinic:'City Health Center',city:'Sylhet',fee:700,img:'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=240&h=280&fit=crop'},
 {id:6,name:'Dr. Mahir Chowdhury',specialty:'Orthopedics',degree:'MBBS, MS (Orthopedics)',experience:14,clinic:'Central Care Hospital',city:'Dhaka',fee:1300,img:'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=240&h=280&fit=crop'}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let appointments=read('shifa-appointments',[]),profile=read('shifa-profile',{name:'Ayesha Rahman',email:'ayesha@example.com',phone:'',city:'Dhaka'}),exceptions=read('shifa-exceptions',[]),lang=read('shifa-language','en'),current='home',filter={q:'',specialty:'',city:'',fee:'',sort:''},tab='upcoming',booking=null;
function save(){try{localStorage.setItem('shifa-appointments',JSON.stringify(appointments));localStorage.setItem('shifa-profile',JSON.stringify(profile));localStorage.setItem('shifa-exceptions',JSON.stringify(exceptions))}catch{toast('Browser storage is unavailable. Changes will last for this visit only.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function money(n){return new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-BD',{style:'currency',currency:'BDT',maximumFractionDigits:0}).format(n)}
function day(offset=1){const date=new Date(Date.now()+offset*86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function dateLabel(date){return new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-GB',{timeZone:'Asia/Dhaka',day:'numeric',month:'short',year:'numeric'}).format(new Date(date+'T12:00:00+06:00'))}
function future(a){return new Date(a.date+'T'+a.time+':00+06:00')>new Date()}
const nav=[['home','⌂','Overview','হোম'],['doctors','♧','Find a doctor','ডাক্তার'],['appointments','▦','Appointments','অ্যাপয়েন্টমেন্ট'],['profile','♙','My profile','প্রোফাইল'],['doctor','◷','Doctor portal','ডাক্তার পোর্টাল'],['admin','⊞','Administration','প্রশাসন']];
function renderNav(){$('#navigation').innerHTML=nav.map(([page,icon,en,bn])=>`<a href="#${page}" class="nav-item ${current===page?'active':''}" ${current===page?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${lang==='bn'?bn:en}</a>`).join('');$('#language').textContent=lang==='bn'?'English':'বাংলা';document.documentElement.lang=lang;$('.user-button').innerHTML=`<span class="avatar small">${escape(profile.name.charAt(0)||'P')}</span><span>${escape(profile.name)}<small>Demo patient account</small></span><span>⌄</span>`}
function card(d){return `<article class="doctor-card"><div class="doctor-top"><img class="doctor-photo" src="${d.img}" alt="Illustrative portrait for demo doctor" loading="lazy"><div><h3>${d.name}</h3><div class="specialization">${d.specialty}</div><p>${d.degree}</p><span class="demo-label">FICTIONAL DEMO DOCTOR</span></div></div><div class="doctor-meta"><span>◷ ${d.experience} years experience</span><span>⌖ ${d.city}</span></div><div class="doctor-bottom"><div class="fee">${money(d.fee)} <small>/ visit</small></div><button class="secondary" data-doctor="${d.id}">View profile ↗</button></div></article>`}
function intro(title,subtitle){return `<div class="page-intro"><span class="eyebrow">YOUR HEALTH, SIMPLIFIED</span><h1 style="margin-top:10px">${title}</h1><p>${subtitle}</p></div>`}
function upcomingPanel(){const a=appointments.filter(a=>a.status==='confirmed'&&future(a)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];return `<div class="panel"><div class="section-head"><h3>Upcoming appointment</h3><span>↗</span></div>${a?`<span class="upcoming-label">Confirmed · Demo</span><h3>${doctors.find(d=>d.id===a.doctor).name}</h3><div class="appointment-detail"><span class="calendar-icon">▦</span><div>${dateLabel(a.date)}<br><small>${a.time} · Asia/Dhaka</small></div></div><button class="secondary" data-page="appointments">View appointment →</button>`:`<div class="appointment-detail"><span class="calendar-icon">▦</span><div>Your next step to feeling better.<br><small>No appointments booked yet.</small></div></div><button class="secondary" data-page="doctors">Book your first visit →</button>`}</div>`}
function home(){return `<div class="welcome"><div><h1>${lang==='bn'?'সুস্বাগতম':'Hello'}, ${escape(profile.name.split(' ')[0])} <span style="font-size:25px">☀</span></h1><p>${lang==='bn'?'আজ আপনার স্বাস্থ্যের যত্ন নিন।':"Let’s make your health a priority today."}</p></div><button class="location" data-page="profile">⌖ ${escape(profile.city)}, Bangladesh ⌄</button></div><section class="hero"><div class="hero-copy"><span class="eyebrow">A HEALTHIER TOMORROW STARTS HERE</span><h2>The right care.<br>The right doctor.<br><em>Right here.</em></h2><p>Discover specialists, find a time that suits you, and take the next step with confidence.</p><button class="primary" data-page="doctors">Find a doctor <span>↗</span></button></div><div class="hero-art"><img src="https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=850&h=700&fit=crop" alt="Healthcare professional, illustrative stock photograph"><div class="hero-note"><span>✚</span><div><strong>Care built around you</strong><small>From discovery to your next visit</small></div></div></div></section><form class="search-panel" id="home-search"><span style="font-size:23px;color:#93a39b">⌕</span><input name="query" placeholder="Search doctors, specialties, or clinics" aria-label="Search doctors"><select name="city" aria-label="City"><option value="">All cities</option><option>Dhaka</option><option>Chattogram</option><option>Sylhet</option></select><button class="primary">Search <span>→</span></button></form><div class="section-head"><h2>Care for every need</h2><button class="text-button" data-page="doctors">All specialties →</button></div><section class="specialties">${specialties.map(([i,s])=>`<button class="specialty" data-specialty="${s}"><span class="specialty-icon">${i}</span><strong>${s}</strong><small>Explore specialists</small></button>`).join('')}</section><div class="dashboard-grid"><section><div class="section-head"><h2>Meet your care team</h2><button class="text-button" data-page="doctors">View all →</button></div><div class="doctors-grid">${doctors.slice(0,4).map(card).join('')}</div></section><aside class="right-column">${upcomingPanel()}<div class="health-tip"><span class="eyebrow">✧ A MOMENT FOR YOU</span><h3>Small steps.<br>Healthier days.</h3><p>A little time for yourself can make a difference. Keep your next check-in on the calendar.</p><button class="text-button" data-page="appointments" style="padding-left:0;color:#957c51">Your care calendar →</button></div></aside></div><div class="trust-strip"><span><b>♧</b> Explore specialties</span><span><b>▦</b> Book in a few steps</span><span><b>♡</b> Care on your schedule</span></div>`}
function doctorList(){return intro(lang==='bn'?'আপনার ডাক্তার খুঁজুন':'Find your doctor','Explore fictional demo specialists. Real appointments are not available in this demo.')+`<div class="filters"><input id="query" aria-label="Search doctors" placeholder="Name, specialty, or clinic" value="${escape(filter.q)}"><select id="specialty" aria-label="Specialty"><option value="">All specialties</option>${specialties.map(([,s])=>`<option ${filter.specialty===s?'selected':''}>${s}</option>`).join('')}</select><select id="city" aria-label="City"><option value="">All cities</option>${['Dhaka','Chattogram','Sylhet'].map(s=>`<option ${filter.city===s?'selected':''}>${s}</option>`).join('')}</select><select id="fee" aria-label="Maximum fee"><option value="">Any fee</option>${[1000,1500].map(n=>`<option value="${n}" ${filter.fee==n?'selected':''}>Up to ৳${n}</option>`).join('')}</select><select id="sort" aria-label="Sort doctors"><option value="">Recommended</option><option value="fee" ${filter.sort==='fee'?'selected':''}>Fee: low to high</option><option value="experience" ${filter.sort==='experience'?'selected':''}>Most experienced</option></select><button class="text-button" id="reset-filters">Reset</button></div><p id="result-count"></p><div class="doctors-grid all-doctors" id="results"></div>`}
function updateResults(){let list=doctors.filter(d=>(d.name+' '+d.specialty+' '+d.clinic).toLowerCase().includes(filter.q.toLowerCase())&&(!filter.specialty||d.specialty===filter.specialty)&&(!filter.city||d.city===filter.city)&&(!filter.fee||d.fee<=+filter.fee));if(filter.sort==='fee')list.sort((a,b)=>a.fee-b.fee);if(filter.sort==='experience')list.sort((a,b)=>b.experience-a.experience);$('#result-count').textContent=`${list.length} demo specialists found`;$('#results').innerHTML=list.map(card).join('')||'<div class="empty"><h3>No doctors found</h3>Try another city or remove a filter.</div>'}
function appointmentPage(){const list=appointments.filter(a=>tab==='cancelled'?a.status==='cancelled':a.status!=='cancelled'&&(tab==='upcoming'?future(a):!future(a))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return intro('My appointments','A little organization. A little peace of mind. All times are in Asia/Dhaka.')+`<div class="tabs">${['upcoming','past','cancelled'].map(t=>`<button data-tab="${t}" class="${tab===t?'selected':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${list.length?list.map(a=>{const d=doctors.find(d=>d.id===a.doctor);return `<article class="panel appointment-row"><div class="doctor-top"><img class="doctor-photo" src="${d.img}" alt="Illustrative demo portrait"><div><h3>${d.name}</h3><p>${d.specialty} · ${d.clinic}</p><p>${dateLabel(a.date)} · ${a.time} · ${money(d.fee)}</p><small>Demo reference: ${escape(a.id)}</small></div></div><span class="status ${a.status}">${a.status}</span><div>${a.status==='confirmed'&&future(a)?`<button class="text-button" data-reschedule="${a.id}">Reschedule</button><button class="text-button danger" data-cancel="${a.id}">Cancel</button>`:''}</div></article>`}).join(''):`<div class="panel empty"><div style="font-size:35px">▦</div><h3>No ${tab} appointments</h3><p>When you book a demo visit, you’ll find it here.</p><button class="primary" data-page="doctors">Explore doctors →</button></div>`}`}
function profilePage(){return intro('Your profile','Your details, in one place.')+`<div class="notice">Demo profile stored only in this browser. No real authentication is connected. Please use fictional details.</div><div class="profile-layout"><div class="panel" style="text-align:center"><div class="avatar profile-avatar">${escape(profile.name.charAt(0))}</div><h3>${escape(profile.name)}</h3><p>Demo patient</p><button class="text-button danger" id="delete-data">Delete my demo data</button></div><form class="panel" id="profile-form"><h2 style="margin-bottom:25px">Personal information</h2><div class="form-grid"><label class="field">Full name<input name="name" required maxlength="80" value="${escape(profile.name)}"></label><label class="field">Email address<input name="email" type="email" required value="${escape(profile.email)}"></label><label class="field">Phone (optional)<input name="phone" type="tel" pattern="[+0-9 ()-]{7,20}" value="${escape(profile.phone)}"></label><label class="field">City<select name="city">${['Dhaka','Chattogram','Sylhet'].map(c=>`<option ${profile.city===c?'selected':''}>${c}</option>`).join('')}</select></label></div><button class="primary">Save changes →</button></form></div>`}
function portal(admin=false){const active=appointments.filter(a=>a.status==='confirmed'&&(admin||a.doctor===1));return intro(admin?'Administration':'Doctor workspace',admin?'Demo overview of the SHIFA booking experience.':'Demo schedule for Dr. Farhana Ahmed.')+`<div class="notice">Public demo interface — no privileged access or real patient data. Live doctor/admin workflows require authenticated server-side roles and authorization.</div><div class="metrics"><div class="panel metric"><small>Demo doctors</small><strong>${admin?doctors.length:1}</strong><small>${admin?'Across 6 specialties':'Dr. Farhana Ahmed'}</small></div><div class="panel metric"><small>Active bookings</small><strong>${active.length}</strong><small>This browser only</small></div><div class="panel metric"><small>Practice locations</small><strong>${admin?5:1}</strong><small>Fictional demo clinics</small></div></div>${!admin?`<form id="availability-form" class="panel" style="margin-bottom:20px"><h3>Schedule exceptions</h3><p>Block a date for this demo doctor. Existing bookings remain visible.</p><div class="filters"><input type="date" name="date" min="${day(1)}" required aria-label="Date to block"><button class="primary">Block date</button></div>${exceptions.map(date=>`<button type="button" class="secondary" data-unblock="${date}">${dateLabel(date)} ×</button>`).join(' ')}</form>`:''}<section class="panel"><h2 style="margin-bottom:20px">${admin?'Appointment overview':'Your appointments'}</h2>${active.length?active.map(a=>`<div class="appointment-row"><div><strong>${doctors.find(d=>d.id===a.doctor).name}</strong><p>${dateLabel(a.date)} · ${a.time} · Demo patient</p></div><span class="status">Confirmed</span></div>`).join(''):'<p>No demo appointments yet. Book a visit to populate this view.</p>'}</section>${admin?`<section class="panel" style="margin-top:20px"><h2>Doctor directory</h2>${doctors.map(d=>`<div class="appointment-row" style="margin-top:20px"><div><strong>${d.name}</strong><p>${d.specialty} · ${d.city}</p></div><span class="demo-label">NOT VERIFIED · DEMO</span><button class="text-button" data-doctor="${d.id}">Inspect profile →</button></div>`).join('')}</section>`:''}`}
function render(){current=location.hash.slice(1)||'home';if(!nav.some(n=>n[0]===current))current='home';renderNav();$('#main').innerHTML=({home,doctors:doctorList,appointments:appointmentPage,profile:profilePage,doctor:()=>portal(),admin:()=>portal(true)})[current]();if(current==='doctors')updateResults();$('#year').textContent=new Date().getFullYear()}
function go(page){if(location.hash==='#'+page)render();else location.hash=page;window.scrollTo({top:0,behavior:'instant'})}
function modal(content){const d=$('#dialog');d.innerHTML=content;if(!d.open)d.showModal()}
function modalHead(title){return `<div class="dialog-head"><h2>${title}</h2><button class="close" id="close-dialog" aria-label="Close dialog">×</button></div>`}
function showDoctor(id){const d=doctors.find(d=>d.id===id);modal(modalHead('Meet your specialist')+`<div class="profile-hero"><img src="${d.img}" alt="Illustrative demo portrait"><div><span class="demo-label">FICTIONAL DEMO DOCTOR · NOT VERIFIED</span><h2>${d.name}</h2><div class="specialization">${d.specialty}</div><p>${d.degree}</p></div></div><p>This fictional profile demonstrates doctor discovery and appointment booking. Images are illustrative stock photography; qualifications and clinics are demo content.</p><div class="detail-grid"><div><small>Experience</small>${d.experience} years</div><div><small>Consultation fee</small>${money(d.fee)}</div><div><small>Practice location</small>${d.clinic}, ${d.city}</div><div><small>Languages</small>English, Bangla</div></div><button class="primary wide" data-book="${d.id}">Book a demo appointment →</button>`)}
const times=['09:00','09:30','10:00','10:30','11:00','11:30','14:00','14:30','15:00'];
function unavailable(date,time){return (booking.doctor===1&&exceptions.includes(date))||appointments.some(a=>a.id!==booking.original&&a.doctor===booking.doctor&&a.date===date&&a.time===time&&a.status==='confirmed')}
function startBooking(id,original=null){booking={doctor:id,date:day(1),time:'',original};showBooking()}
function showBooking(){const d=doctors.find(d=>d.id===booking.doctor);modal(modalHead(booking.original?'Reschedule appointment':'Choose your appointment')+`<div class="steps">01 SELECT A TIME → 02 REVIEW → 03 CONFIRM</div><div class="notice">Demo booking only. No clinic will receive this reservation.</div><h3>${d.name}</h3><p>${d.specialty} · ${money(d.fee)} / 30-minute visit</p><label class="field">Consultation location<select id="booking-clinic"><option>${d.clinic}, ${d.city}</option></select></label><label class="field">Consultation type<select><option>In-person consultation</option></select></label><label class="field">Appointment date<input type="date" id="booking-date" min="${day(1)}" max="${day(60)}" value="${booking.date}" required></label><strong style="font-size:12px">Available times · Asia/Dhaka</strong><div class="slots">${times.map(t=>`<button class="slot ${booking.time===t?'selected':''}" data-time="${t}" ${unavailable(booking.date,t)?'disabled':''}>${t}</button>`).join('')}</div><button class="primary wide" id="review-booking" ${booking.time?'':'disabled'}>Review appointment →</button>`)}
function reviewBooking(){const d=doctors.find(d=>d.id===booking.doctor);modal(modalHead('Review your appointment')+`<div class="steps">01 SELECT A TIME → 02 REVIEW → 03 CONFIRM</div><div class="booking-summary"><strong>${d.name}</strong><br>${d.specialty}<br>${d.clinic}, ${d.city}<br>${dateLabel(booking.date)} at ${booking.time} (Asia/Dhaka)<br>In-person · 30 minutes<br><strong>Consultation fee: ${money(d.fee)}</strong><br>Patient: ${escape(profile.name)}</div><p>No payment is collected. Demo cancellations are allowed until the appointment starts. Rescheduling keeps the original booking until the replacement is saved.</p><button class="primary wide" id="confirm-booking">Confirm demo appointment →</button><button class="text-button wide" id="back-booking">← Change time</button>`)}
function confirmBooking(){if(!booking?.time)return;appointments=read('shifa-appointments',appointments);if(unavailable(booking.date,booking.time)){toast('That time is no longer available. Choose another slot.');booking.time='';showBooking();return}if(booking.date<day(1)||booking.date>day(60)){toast('Choose a date within the next 60 days.');return}const id='SHF-'+crypto.randomUUID().slice(0,8).toUpperCase();const original=appointments.find(a=>a.id===booking.original);if(original)original.status='cancelled';appointments.push({...booking,id,status:'confirmed',createdAt:new Date().toISOString()});save();const a={...booking};booking=null;modal(modalHead('You’re all set')+`<div class="confirmation"><div class="success-icon">✓</div><h2>Your demo visit is booked.</h2><p>${dateLabel(a.date)} at ${a.time} · Asia/Dhaka</p><div class="booking-summary">Booking reference: <strong>${id}</strong><br>${doctors.find(d=>d.id===a.doctor).name}<br>Demo only. No real appointment was created.</div><button class="primary wide" id="view-appointments">Go to my appointments →</button></div>`);render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.specialty){filter={q:'',specialty:b.dataset.specialty,city:'',fee:'',sort:''};go('doctors')}if(b.dataset.doctor)showDoctor(+b.dataset.doctor);if(b.dataset.book)startBooking(+b.dataset.book);if(b.dataset.time){booking.time=b.dataset.time;showBooking()}if(b.dataset.tab){tab=b.dataset.tab;render()}if(b.dataset.cancel){modal(modalHead('Cancel demo appointment?')+`<p>This releases the selected demo time. You can book again from the doctor’s profile.</p><button class="primary wide" data-confirm-cancel="${b.dataset.cancel}">Yes, cancel appointment</button>`)}if(b.dataset.confirmCancel){const a=appointments.find(a=>a.id===b.dataset.confirmCancel);if(a&&future(a)){a.status='cancelled';save();$('#dialog').close();render();toast('Demo appointment cancelled.')}}if(b.dataset.reschedule){const a=appointments.find(a=>a.id===b.dataset.reschedule);startBooking(a.doctor,a.id)}if(b.dataset.unblock){exceptions=exceptions.filter(x=>x!==b.dataset.unblock);save();render()}switch(b.id){case'close-dialog':$('#dialog').close();break;case'review-booking':reviewBooking();break;case'confirm-booking':confirmBooking();break;case'back-booking':showBooking();break;case'view-appointments':$('#dialog').close();go('appointments');break;case'reset-filters':filter={q:'',specialty:'',city:'',fee:'',sort:''};render();break;case'language':lang=lang==='en'?'bn':'en';try{localStorage.setItem('shifa-language',JSON.stringify(lang))}catch{}render();toast(lang==='bn'?'বাংলা নেভিগেশন চালু হয়েছে। সম্পূর্ণ অনুবাদ শীঘ্রই।':'English navigation enabled.');break;case'notifications':modal(modalHead('Your notifications')+(appointments.length?appointments.slice().reverse().map(a=>`<div class="notification">Demo appointment ${a.status}<small>${dateLabel(a.date)} · ${a.time} · ${escape(a.id)}</small></div>`).join(''):'<div class="empty"><h3>You’re all caught up</h3>Booking updates will appear here.</div>'));break;case'delete-data':modal(modalHead('Delete demo data?')+'<p>This removes your profile, appointments, and schedule exceptions from this browser.</p><button class="primary wide" id="confirm-delete">Delete demo data</button>');break;case'confirm-delete':for(const key of ['shifa-profile','shifa-appointments','shifa-exceptions','shifa-language'])localStorage.removeItem(key);appointments=[];exceptions=[];profile={name:'Demo Patient',email:'patient@example.com',phone:'',city:'Dhaka'};$('#dialog').close();render();toast('Your demo data was deleted.');break}});
document.addEventListener('input',e=>{if(e.target.id==='query'){filter.q=e.target.value;updateResults()}});
document.addEventListener('change',e=>{if(['specialty','city','fee','sort'].includes(e.target.id)){filter[e.target.id]=e.target.value;updateResults()}if(e.target.id==='booking-date'){if(e.target.validity.valid){booking.date=e.target.value;booking.time='';showBooking()}else toast('Select a date within the next 60 days.')}});
document.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='home-search'){filter={q:f.get('query').trim(),city:f.get('city'),specialty:'',fee:'',sort:''};go('doctors')}if(e.target.id==='profile-form'){if(!f.get('name').trim())return;profile=Object.fromEntries(f);profile.name=profile.name.trim();save();render();toast('Demo profile saved.')}if(e.target.id==='availability-form'){const date=f.get('date');if(!exceptions.includes(date))exceptions.push(date);save();render();toast('Demo schedule updated.')}});
window.addEventListener('hashchange',render);window.addEventListener('storage',e=>{if(e.key==='shifa-appointments'){appointments=read(e.key,[]);render()}});render();
